import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D_ZOUi6P.js";const u=JSON.parse('{"title":"Conventions","description":"","frontmatter":{},"headers":[],"relativePath":"development/conventions.md","filePath":"development/conventions.md","lastUpdated":1793273055000}'),s={name:"development/conventions.md"};function r(i,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h1><p>This page collects the project-specific rules that aren&#39;t mechanical enough for the <a href="./style-guide">style guide</a> or a lint: design preferences, scope decisions, and matters of taste. Reviewers call these out in PR reviews when they&#39;re missed.</p><p>When a review or a design discussion settles a question that&#39;s likely to come up again, add it here.</p><h2 id="code-comments" tabindex="-1">Code comments <a class="header-anchor" href="#code-comments" aria-label="Permalink to &quot;Code comments&quot;">​</a></h2><p>Keep code comments, including rustdoc on private items, short. A comment should do one of two things:</p><ul><li>flag a caveat that a reader could easily miss</li><li>annotate a large block of logic at a high level, so that it&#39;s easier to navigate</li></ul><p>Don&#39;t write comments that restate what the code already says, and don&#39;t re-explain the design at every call site. Explain a design once, in the module documentation, and keep comments at call sites to a sentence or two. Before keeping a comment, ask whether deleting it would make the reader miss anything.</p><h2 id="generated-and-vendored-files" tabindex="-1">Generated and vendored files <a class="header-anchor" href="#generated-and-vendored-files" aria-label="Permalink to &quot;Generated and vendored files&quot;">​</a></h2><p>Never hand-edit files marked <code>@generated</code> or <code>DO NOT EDIT</code>: change their source of truth and regenerate them. The vendored Datadog configuration schema under <code>lib/datadog-agent/config/schema/core/</code> is a pristine upstream copy; see <a href="./configuration-system">Configuration system</a> for how to change what it feeds into.</p><h2 id="hot-paths" tabindex="-1">Hot paths <a class="header-anchor" href="#hot-paths" aria-label="Permalink to &quot;Hot paths&quot;">​</a></h2><p>Much of Saluki processes high volumes of metrics, logs, and traces. In code that runs per event, avoid heap allocations, clones, and string formatting that aren&#39;t needed, unbounded buffers or queues, and logging at any level whose volume scales with event volume.</p><h2 id="supervision-and-shutdown" tabindex="-1">Supervision and shutdown <a class="header-anchor" href="#supervision-and-shutdown" aria-label="Permalink to &quot;Supervision and shutdown&quot;">​</a></h2><p>Every supervised child declares its own shutdown strategy, and whoever owns it, whether a supervisor or a scope, enforces exactly that strategy:</p><ul><li>Don&#39;t special-case supervisors versus workers when it comes to deadlines.</li><li>Don&#39;t hold back deadline margins, or pass an owner&#39;s deadline down to its children.</li><li>If something outside has a shorter limit, it preempts by aborting the subtree. That&#39;s by design.</li></ul><p>A component that overruns its grace period is a bug in that component. Fix it with rigorous code and tests rather than hiding it with runtime deadline tricks.</p><h2 id="api-routes-and-control-plane-workers" tabindex="-1">API routes and control plane workers <a class="header-anchor" href="#api-routes-and-control-plane-workers" aria-label="Permalink to &quot;API routes and control plane workers&quot;">​</a></h2><p>Publish internal API routes and gRPC services by asserting a dynamic route from a worker, rather than registering static handlers on the API builder. Dynamic routes let any worker in the supervision tree contribute to an endpoint it doesn&#39;t own, which keeps workers composable.</p><p>Shared crates provide workers, and each binary assembles its own supervisors from them. Don&#39;t wrap supervisor construction in a library builder.</p><h2 id="project-scope" tabindex="-1">Project scope <a class="header-anchor" href="#project-scope" aria-label="Permalink to &quot;Project scope&quot;">​</a></h2><ul><li>The <code>standalone</code> mode of <code>agent-data-plane</code> is left over from earlier development and testing. It isn&#39;t for production use, and supporting it shouldn&#39;t block feature development.</li><li><code>panoramic</code> and <code>stele</code> under <code>bin/correctness/</code> are our own black-box correctness and integration tools. They don&#39;t replace unit tests for the branches inside a crate, and they aren&#39;t the Antithesis platform, which lives separately under <code>test/antithesis/</code>. See <a href="./testing">Testing</a>.</li></ul>',20)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
